// SetChatPinnedMessage sets or clears the pinned message id on a chat.
// The pinned_message_id stores the creator-owned copy's local_id; fanout_id
// resolves that logical message to each member's local copy. NULL clears the pin.
func (q *Queries) SetChatPinnedMessage(ctx context.Context, arg SetChatPinnedMessageParams) (Chat, error) {
	row := q.db.QueryRow(ctx, setChatPinnedMessage, arg.ID, arg.PinnedMessageID)
	var i Chat
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.CreatorID,
		&i.Version,
		&i.Date,
		&i.PinnedMessageID,
		&i.DefaultBannedRights,
	)
	return i, err
}

const setChatTitle = `-- name: SetChatTitle :one
UPDATE chats SET title = $2, version = version + 1 WHERE id = $1 RETURNING id, title, creator_id, version, date, pinned_message_id, default_banned_rights
`

type SetChatTitleParams struct {
	ID    int64
	Title string
}

func (q *Queries) SetChatTitle(ctx context.Context, arg SetChatTitleParams) (Chat, error) {
	row := q.db.QueryRow(ctx, setChatTitle, arg.ID, arg.Title)
	var i Chat
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.CreatorID,
		&i.Version,
		&i.Date,
		&i.PinnedMessageID,
		&i.DefaultBannedRights,
	)
	return i, err
}
